import json
from pathlib import Path

SOURCES = json.loads(Path('source.json').read_text())
REFERENCES = json.loads(Path('reference-targets.json').read_text())
ANSWERS = {}


def article(number, paragraphs, reason, notes, removed=None, benefit=None, checks=None, repeal=None):
    source = next(s for s in SOURCES if s['number'] == number)
    result = {k: source[k] for k in ('code_id', 'source_id', 'source_sha256', 'number')}
    result.update(proposed_xml='\n'.join('<p>' + p + '</p>' for p in paragraphs),
                  reason=reason, review_notes=notes, status='rewrite_draft')
    if removed:
        result.update(change_type='normative_reduction',
                      reform_policy_id='editorial_direction_2026_10_19', removed_provisions=removed)
    if repeal:
        result.update(change_type='full_repeal',
                      repeal_policy_id='editorial_direction_2026_10_19', repeal_scope=repeal)
    if benefit:
        result['benefit_review'] = benefit
    if checks:
        result['reference_checks'] = []
        for number_target, assessment in checks.items():
            key, target = next((k, v) for k, v in REFERENCES['targets'].items() if v['number'] == number_target)
            result['reference_checks'].append(dict(target_key=key, view_sha256=target['view_sha256'], assessment=assessment))
    ANSWERS[number] = result


